pub fn apply(
    pair: Pair,
    facts: &dyn crate::unit_store::EvidenceFacts,
    graph: &crate::producer::Graph,
) -> Result<Pair, String> {
    let pair = install_locations(pair, facts, graph)?;
    let mut pair = install_value_contracts(pair, facts)?;
    install_evidence(&mut pair.pdg, facts)?;
    origins::install(&mut pair, facts)?;

    let pair = install_annotations(
        pair,
        size_calls::sources(facts),
        crate::size_calls::KEY,
        |source| crate::size_calls::semantics(source, facts),
    )?;
    let pair = install_annotations(
        pair,
        checked_lengths::sources(facts),
        crate::checked_lengths::KEY,
        |source| checked_lengths::semantics(source, facts),
    )?;
    let pair = install_annotations(
        pair,
        bool_usize::sources(facts),
        crate::bool_usize::KEY,
        |source| crate::bool_usize::semantics(source, facts),
    )?;
    install_annotations(
        pair,
        float_scalars::sources(facts),
        crate::float_scalars::KEY,
        |source| crate::float_scalars::semantics(source, facts),
    )
}

fn install_locations(
    mut pair: Pair,
    facts: &dyn crate::unit_store::EvidenceFacts,
    graph: &crate::producer::Graph,
) -> Result<Pair, String> {
    let fields = observations(facts)?;
    let mut context = LocationContext::new(facts);
    let locations = fields
        .operations
        .iter()
        .filter(|field| matches!(field.location, Location::Captured { .. }))
        .map(|field| install_field(&mut pair.pdg, field, &mut context))
        .collect::<Result<BTreeMap<_, _>, _>>()?;

    let derived = install_derived_reads(&mut pair, &mut context)?;
    let memory = install_memory(&mut pair, &mut context, graph)?;
    finish_locations(
        pair,
        crate::helper_reads::merge_locations(
            crate::helper_reads::merge_locations(locations, derived)?,
            memory,
        )?,
    )
}

fn install_memory(
    pair: &mut Pair,
    context: &mut LocationContext<'_>,
    graph: &crate::producer::Graph,
) -> Result<BTreeMap<String, crate::MemoryLocation>, String> {
    let accesses = mutable_scalars::install(pair, context)?;
    let roots = memory_flow::install(pair, context, graph)?;

    crate::helper_reads::merge_locations(accesses, roots)
}

fn verify_mode(
    environment: &Environment,
    facts: &HirFnFacts,
    target: &Namespace,
    mode: SourceMode,
) -> Result<(), String> {
    let reference_product = !matches!(mode, SourceMode::Cleanup);
    let cfgs = &facts.build.cfgs;
    let ownership_engine = supports(facts, OWNERSHIP_MACROS_CAPABILITY)?;
    let external_macros = supports(facts, external_expression_macros::CAPABILITY)?;
    let enums = enum_globs::Scope::new(
        &environment.modules,
        cfgs,
        reference_product || supports(facts, enum_errors::CAPABILITY)?,
    )?;

    let mut visitor = Closure {
        dependency_sources: Some(environment),
        digit_products: supports(
            facts,
            crate::scalar_product_instances::activation::VALUE_CAPABILITY,
        )?,
        external_macros,
        ownership_engine,
        library_macro_imports: supports(facts, source_macros::LIBRARY_CAPABILITY)?,
        ownership_macros: ownership_resolver(environment, facts, &enums)?,
        configuration: crate::conditional_source::Configuration::new(cfgs),
        edition: facts.build.edition.known_value(),
        library: crate::data_library::registry_for(facts),
        native_tls: cfgs.iter().any(|cfg| cfg == "target_thread_local"),
        test_marker: supports(facts, enum_errors::CAPABILITY)?,
        enums,
        names: headers::Names::new(target),
        definitions: BTreeMap::new(),
        scopes: Vec::new(),
        error: None,
        collecting: true,
        expansions: 0,
        nested_context: 0,
        generated_context: 0,
        reference_product,
        scalar_bindings: matches!(mode, SourceMode::CopyOwner | SourceMode::ScalarError),
        checked_external_imports: supports(facts, super::super::fresh_products::CAPABILITY)?,
        result_prelude_namespace: result_prelude_namespace(facts, target, mode)?,
    };
    for collecting in [true, false] {
        visitor.pass(environment, collecting)?;
    }
    Ok(())
}

fn pass(&mut self, environment: &Environment, collecting: bool) -> Result<(), String> {
        self.collecting = collecting;
        for module in &environment.modules {
            self.module(environment, module)?;
        }

        self.finish_pass()
    }

fn module(&mut self, environment: &Environment, module: &census::Module) -> Result<(), String> {
        self.begin_module(environment, module)?;

        for item in &module.items {
            self.module_item(environment, module, item)?;
            if let Some(error) = self.error.take() {
                return Err(format!(
                    "{error} [module {}, source {}]",
                    module.namespace.join("::"),
                    module.path.display()
                ));
            }
        }
        Ok(())
    }

pub(super) fn verify<'a>(
    original: &HirFnFacts,
    projected: &'a HirFnFacts,
    scalar: &str,
) -> Result<Checked<'a>> {
    if original.source.bytes.len() > crate::concrete_types::MAX_SOURCE_BYTES
        || original.bindings.len() > 256
        || original.signature.params.len() > 64
    {
        return Err("Scalar instance source exceeds its bounded proof budget".into());
    }
    if !matches!(scalar, "i32" | "u32") {
        return Err("Scalar instance source argument is outside i32/u32".into());
    }

    preserved(original, projected)?;
    let syntax: syn::ItemFn = syn::parse_str(&original.source.bytes).map_err(|e| e.to_string())?;
    let parameter = signature(&syntax)?;
    signature_metadata(&syntax, projected, &parameter)?;

    let mut flow = Flow::new(projected, scalar, parameter)?;
    flow.parameters(&syntax.sig)?;
    let expected = flow.annotation(&syntax.sig.output)?;
    flow.result = expected;

    let actual = flow.block(&syntax.block, &projected.body)?;
    if actual != expected && actual != Value::Never
        || flow.bindings.len() != projected.bindings.len()
    {
        return Err("Scalar instance result or complete binding inventory disagrees".into());
    }
    Ok(Checked(projected))
}

fn new(facts: &'a HirFnFacts, scalar: &'a str, parameter: String) -> Result<Self> {
        let mut inventory = BTreeMap::new();
        for binding in &facts.bindings {
            if inventory.insert(binding.symbol.as_str(), binding).is_some() {
                return Err("Scalar instance binding inventory repeats a symbol".into());
            }
        }
        Ok(Self {
            facts,
            offsets: SpanIndex::new(&facts.source.bytes),
            scalar,
            parameter,
            result: Value::Scalar,
            scope: BTreeMap::new(),
            frames: vec![Vec::new()],
            inventory,
            bindings: BTreeSet::new(),
            seen: BTreeSet::new(),
        })
    }

fn block(&mut self, syntax: &syn::Block, node: &HirNode) -> Result<Value> {
        self.enter_block(syntax, node)?;
        let mut value = Value::Unit;
        for (index, statement) in syntax.stmts.iter().enumerate() {
            if value == Value::Never {
                return Err("Unreachable scalar instance source suffix is unsupported".into());
            }
            value = self.statement(statement, &node.children[index])?;
        }

        self.exit_block()?;
        self.typed(node, value)
    }

fn enter_block(&mut self, syntax: &syn::Block, node: &HirNode) -> Result<()> {
        self.node(node, "expr_block", syntax.span())?;
        if syntax.stmts.len() != node.children.len() {
            return Err("Scalar instance block inventory disagrees".into());
        }

        self.frames.push(Vec::new());
        Ok(())
    }

fn exit_block(&mut self) -> Result<()> {
        for name in self.frames.pop().ok_or("Missing scalar block frame")? {
            self.scope
                .get_mut(&name)
                .ok_or("Missing scalar local binding")?
                .pop();
        }
        Ok(())
    }

