pub(super) fn consume(request: &UnitRequest<'_>, result: &mut Handoff) -> Result<(), String> {
    let unit = request.unit;
    check_mode(unit, &request.capture.plan)?;

    let snapshot = Stage::new("cli.advisory.load_inventory", &unit.target.package, None)
        .observe(|| capture::load_inventory(unit))?;
    if unit.style_inputs_only {
        return consume_style(request, &snapshot, result);
    }
    let stage = Stage::new(
        "cli.advisory.decode",
        &unit.target.package,
        Some(snapshot.bundle.bytes()),
    );
    if header_only(request.args) {
        let facts = stage.observe(|| {
            rstyle_pdg::unit_store::read_diagnostic_snapshot_headers_phase(
                snapshot.bundle.bytes(),
                "compiler-advisory-only",
            )
        })?;
        consume_facts(
            Decoded {
                facts,
                owner: FactOwner::Numeric,
            },
            request,
            &snapshot,
            result,
        )
    } else {
        let facts = stage.observe(|| {
            rstyle_pdg::unit_store::read_diagnostic_snapshot_phase(
                snapshot.bundle.bytes(),
                "compiler-advisory-only",
            )
        })?;
        consume_facts(
            Decoded {
                facts,
                owner: FactOwner::Advisory,
            },
            request,
            &snapshot,
            result,
        )
    }
}

fn consume_facts<B: identity::BodyOwner, L>(
    decoded: Decoded<B, L>,
    request: &UnitRequest<'_>,
    snapshot: &capture::Snapshot,
    result: &mut Handoff,
) -> Result<(), String> {
    let Decoded { facts, owner } = decoded;
    let unit = request.unit;
    let context_stage = Stage::new("cli.advisory.context", &unit.target.package, None).enter();
    let selected = selected_context::SelectedContext::new(unit)?;

    let mut builds = rstyle_pdg::nominal_binding::BuildContexts::default();
    for function in &facts {
        verify_frontend_invocation(function, unit, request.capture, &selected)?;
        builds.intern(&function.build)?;
    }

    result
        .source_inventory
        .extend(source_inventory(unit, snapshot)?);
    result.build_contexts.push(UnitBuildContexts {
        unit_bundle: unit.directory.join("unit.evidence.json"),
        builds,
    });
    context_stage.finish(Ok::<_, String>(()))?;
    Stage::new("cli.advisory.retain", &unit.target.package, None).observe(|| {
        let keys = identity::functions(request.id, &facts)?;
        retain(owner(Arc::new(facts)), keys, request, result)
    })
}

fn selected_workspace(cli: &Cli) -> Result<(crate::workspace::Metadata, Value), String> {
    let raw = crate::workspace::load_with_toolchain(
        cli.manifest_path.as_deref(),
        Some(&run::pinned_toolchain()),
    )?;
    let metadata = crate::workspace::Metadata::deserialize(&raw)
        .map_err(|e| format!("cargo metadata: {e}"))?;
    if let Some(package) = metadata.unknown_packages(&cli.packages).first() {
        return Err(format!("unknown package {package}"));
    }
    Ok((metadata, raw))
}

fn capture_unit(
    plan: &Path,
    target: Target,
    invocation: Vec<String>,
    mut command: Command,
) -> Result<u8, String> {
    if invocation
        .iter()
        .any(|arg| arg.starts_with("incremental=") || arg.starts_with("-Cincremental="))
    {
        return Err("strict capture requires incremental compilation disabled; remove explicit -C incremental flags".into());
    }
    let root = plan.parent().ok_or("missing run directory")?;
    let selected_plan: Plan = read_json(plan)?;
    let directory = tempfile::Builder::new()
        .prefix("invocation-")
        .tempdir_in(root)
        .map_err(|e| e.to_string())?
        .keep();
    let test = invocation.iter().any(|a| a == "--test");
    let unit = Unit {
        compiler_advisory_only: selected_plan.compiler_advisory_only,
        style_inputs_only: selected_plan.style_inputs_only,
        extraction_profile: selected_plan.extraction_profile,
        target,
        test,
        invocation,
        directory,
        artifacts: Vec::new(),
    };
    let status = invoke_unit(&unit, &mut command)?;

    if !status.success() {
        return Ok(2);
    }
    publish_unit(&selected_plan, root, unit)?;
    Ok(0)
}

pub(in crate::clones) fn apply(
        self,
        ctx: &report::Context<'_>,
        mut store: Option<ReviewStore>,
    ) -> Result<Reports, String> {
        let mut reports = evaluate(&self, ctx, store.as_mut())?;
        reports.pruning = pruning(store.as_mut(), reports.status.as_ref(), ctx)?;

        if (!ctx.args.dismiss_helper_pair.is_empty()
            || ctx.args.dismiss_enum_dispatch.is_some()
            || !ctx.args.dismiss_capability_pair.is_empty()
            || ctx.args.dismiss_parameter.is_some()
            || ctx.args.dismiss_length.is_some()
            || ctx.args.dismiss_spacing.is_some()
            || ctx.args.dismiss_mutation_per_target.is_some()
            || ctx.args.dismiss_mutated_targets.is_some()
            || ctx.args.dismiss_density.is_some()
            || !ctx.args.dismiss_compiler_pattern.is_empty()
            || !ctx.args.import_legacy_pattern.is_empty()
            || !ctx.args.dismiss_compiler_diagnostic.is_empty()
            || !ctx.args.dismiss_guard.is_empty()
            || reports
                .pruning
                .as_ref()
                .is_some_and(|report| report.removed_entries > 0))
            && let (Some(path), Some(store)) = (&ctx.args.review_file, &store)
        {
            save(path, store)?;
        }
        Ok(reports)
    }

pub(super) fn optional_requests<T: serde::de::DeserializeOwned>(
    variable: &str,
) -> Result<Option<T>, String> {
    let Some(path) = std::env::var_os(variable) else {
        return Ok(None);
    };
    let file = std::fs::File::open(path).map_err(|error| error.to_string())?;
    serde_json::from_reader(file)
        .map(Some)
        .map_err(|error| error.to_string())
}

pub(crate) fn capture(
    tcx: TyCtxt<'_>,
    scanned: &[source::Function],
    options: &Options<'_>,
) -> Result<(), String> {
    let Some(requests): Option<Requests> =
        diagnostic_support::optional_requests("RSTYLE_DIAGNOSTIC_PRODUCT_INSTANCE_REQUESTS")?
    else {
        return Ok(());
    };
    validate(&requests, tcx, options)?;
    let owners = diagnostic_support::owners(tcx, &[DefKind::AssocFn]);
    let entries = requests
        .requests
        .into_iter()
        .map(|request| {
            let outcome = match owners.get(&request.function).copied().flatten() {
                Some(owner) => observe_owner(tcx, owner, &request, Inputs { scanned, options }),
                None => Outcome::Unavailable {
                    reason: "Original associated owner is unavailable or ambiguous".into(),
                },
            };
            Entry { request, outcome }
        })
        .collect();

    diagnostic_support::persist(
        &Inventory {
            identity: "rstyle.diagnostic.product-instance-bodies/1",
            scope: "original associated Match constructor, Span/Range substitutions and selected Into/From observations only",
            admission_authority: false,
            requests: entries,
        },
        "product-instances",
        "Product diagnostics require an explicit snapshot directory",
    )
}

pub(crate) fn capture(
    tcx: TyCtxt<'_>,
    scanned: &[source::Function],
    options: &Options<'_>,
) -> Result<(), String> {
    let Some(requests): Option<Requests> =
        diagnostic_support::optional_requests("RSTYLE_DIAGNOSTIC_REFERENCE_INSTANCE_REQUESTS")?
    else {
        return Ok(());
    };
    validate(&requests, tcx, options)?;

    let owners = diagnostic_support::owners(tcx, &[DefKind::Fn, DefKind::AssocFn]);
    let entries = requests.requests.into_iter().map(|request| {
        let outcome = match owners.get(&request.function).copied().flatten() {
            Some(id) => observe(Owner { tcx, id }, &request, scanned, options),
            None => Outcome::Unavailable {
                reason: "Original owning function is absent or ambiguous".into(),
            },
        };
        Entry { request, outcome }
    });

    diagnostic_support::persist(
        &Inventory {
            identity: "rstyle.diagnostic.reference-instance-bodies/1",
            scope: "original owning-body observations only; no lifetime, cleanup, origin, artifact or admission authority",
            admission_authority: false,
            requests: entries.collect(),
        },
        "reference-instances",
        "Reference diagnostics require an explicit snapshot directory",
    )
}

pub fn write_sealed_style_snapshot(
    writer: impl Write,
    phase: &str,
    facts: &[StyleFnFacts],
) -> Result<super::super::super::BundleManifest, String> {
    super::super::super::manifest::seal(writer, |writer| {
        let encoded = function_sources::encode_with(
            facts,
            |facts| (&facts.body, &facts.bindings),
            option_bundle::Inventories::with_shared_options(),
        )?;
        let export = Export {
            schema: STYLE_FACTS_SCHEMA,
            phase,
            sources: encoded.snapshots,
            inherent_units: encoded.inventories,
            facts: encoded.functions,
        };
        serde_json::to_writer(writer, &export).map_err(|error| error.to_string())
    })
}

pub fn read_style_snapshot_phase(
    bytes: &[u8],
    expected: &str,
) -> Result<Vec<StyleFnFacts>, String> {
    let parse =
        crate::diagnostics::Stage::new("diagnostic.parse", "style-snapshot", Some(bytes)).enter();
    let wire: Import<HirRef, Uncaptured> =
        parse.finish(serde_json::from_slice(bytes).map_err(|error| error.to_string()))?;

    let restore =
        crate::diagnostics::Stage::new("diagnostic.restore", "style-snapshot", None).enter();
    if ![STYLE_FACTS_SCHEMA, "rstyle.diagnostic.style-facts/1"].contains(&wire.schema.as_str())
        || wire.phase.is_empty()
        || wire.phase != expected
    {
        return Err("Unsupported or mismatched root style snapshot schema or phase".into());
    }
    let shared_options = wire.schema == STYLE_FACTS_SCHEMA;
    restore.finish(restore_snapshot(wire, true, false, shared_options))
}

pub(super) fn seal<W: Write>(
    writer: W,
    publish: impl FnOnce(&mut dyn Write) -> Result<(), String>,
) -> Result<BundleManifest, String> {
    let mut recorder = Recorder {
        writer,
        hash: Xxh3::new(),
        bytes: 0,
    };
    publish(&mut recorder)?;
    recorder.flush().map_err(|error| error.to_string())?;

    Ok(BundleManifest {
        schema: SCHEMA.into(),
        checksum: encode(recorder.hash.digest()),
        bytes: recorder.bytes,
    })
}
